primaryQuery:
run: order_items extend { join_one: u is users on user_id = u.id } -> {
  group_by: channel is u.traffic_source
  aggregate: revenue is round(sale_price.sum(), 2)
  order_by: revenue desc
}

verifyQuery:
run: users extend {
  join_many: oi is order_items on id = oi.user_id
} -> {
  group_by: channel is traffic_source
  aggregate: revenue is round(oi.sale_price.sum(), 2)
  order_by: revenue desc
}
